import org.junit.Test;
import static org.junit.Assert.*;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class CommentsConfigurationTest {

    @Test
    public void newCommentsConfiguration_isInitializedCorrectly() {
        assertTrue(new CommentsConfiguration().isEmpty());
    }

    @Test
    public void existingCommentsConfiguration_isInitializedCorrectly() {
        Map<String, List<String>> comments = new HashMap<>();
        comments.put("test", Arrays.asList("line1", "line2"));
        CommentsConfiguration config = new CommentsConfiguration(comments);
        assertEquals(comments, config.getAllComments());
    }

    @Test
    public void setComment_overwritesExistingCommentsCorrectly() {
        Map<String, List<String>> comments = new HashMap<>();
        comments.put("test", Arrays.asList("line1", "line2"));
        CommentsConfiguration config = new CommentsConfiguration(comments);
        config.setComment("test", "line3", "line4");
        assertEquals(Arrays.asList("line3", "line4"), config.getAllComments().get("test"));
    }

    @Test
    public void setComment_setsNewLinesAsEmptyLines() {
        Map<String, List<String>> comments = new HashMap<>();
        CommentsConfiguration config = new CommentsConfiguration(comments);
        config.setComment("test", "", "");
        assertEquals(Collections.singletonList(""), config.getAllComments().get("test"));
    }

    @Test
    public void setComment_throwsNullPointerException_onNullPath() {
        assertThrows(NullPointerException.class, () -> new CommentsConfiguration().setComment(null, "line1", "line2"));
    }

    @Test
    public void getAllComments_returnsUnmodifiableMap() {
        Map<String, List<String>> comments = new HashMap<>();
        comments.put("test", Arrays.asList("line1", "line2"));
        CommentsConfiguration config = new CommentsConfiguration(comments);
        assertTrue(config.getAllComments().isUnmodifiable());
    }
}
